import{_ as t,c as o,o as n,ai as a}from"./chunks/framework.DGC6THIZ.js";const p=JSON.parse('{"title":"Project Community Managers Monthly Sync","description":"","frontmatter":{"title":"Project Community Managers Monthly Sync","date":"2026-07-09","banner":"assets/events/20260709_project_cm_sync_banner.svg","bannerMobile":"assets/events/20260709_project_cm_sync_banner_mobile.svg","bannerSmall":"assets/events/20260709_project_cm_sync_banner_small.svg","backgroundhex":"#889aa4ff","tags":["neonephos","community","project-community-managers"],"rssPubDate":"2026-07-09","published":true,"sidebar":false,"aside":false,"prev":false,"next":false,"layout":"EventEntryThemeComponent"},"headers":[],"relativePath":"events/2026_07_09_Project_CM_sync.md","filePath":"events/2026_07_09_Project_CM_sync.md"}'),r={name:"events/2026_07_09_Project_CM_sync.md"};function s(i,e,l,h,c,m){return n(),o("div",null,e[0]||(e[0]=[a('<h1 id="project-community-managers-sync" tabindex="-1">Project Community Managers Sync <a class="header-anchor" href="#project-community-managers-sync" aria-label="Permalink to &quot;Project Community Managers Sync&quot;">​</a></h1><p>A recurring, peer-led space for the people doing the quiet, essential work behind every NeoNephos project — welcoming contributors, keeping communities engaged, and figuring out what actually works.</p><p>Every project is solving the same problems in parallel. This sync exists so we stop solving them alone.</p><h2 id="what-this-is" tabindex="-1">What this is <a class="header-anchor" href="#what-this-is" aria-label="Permalink to &quot;What this is&quot;">​</a></h2><ul><li><strong>Peer-led and bi-directional.</strong> No presentations. No reporting up. No imposed agenda.</li><li><strong>A working session, not a status meeting.</strong> Bring your real challenges, your experiments, your wins — we work through them together.</li><li><strong>Community management as shared infrastructure.</strong> The techniques that make one project&#39;s onboarding smooth are almost certainly useful for another. When we share, we compound.</li></ul><h2 id="what-to-bring" tabindex="-1">What to bring <a class="header-anchor" href="#what-to-bring" aria-label="Permalink to &quot;What to bring&quot;">​</a></h2><p>Come prepared to share, not just to listen:</p><ul><li>A challenge you&#39;re stuck on</li><li>An experiment that worked — or didn&#39;t</li><li>A pattern you&#39;ve noticed</li><li>A question you&#39;ve been sitting on because there was nobody obvious to ask</li></ul><p>The more openly we exchange, the more useful this becomes for all of us.</p><h2 id="who-this-is-for" tabindex="-1">Who this is for <a class="header-anchor" href="#who-this-is-for" aria-label="Permalink to &quot;Who this is for&quot;">​</a></h2><p>Community managers, DevRels, maintainers wearing a community hat — anyone across NeoNephos projects doing the work of growing and sustaining a contributor community.</p><h2 id="interested-in-joining-us" tabindex="-1">Interested in joining us? <a class="header-anchor" href="#interested-in-joining-us" aria-label="Permalink to &quot;Interested in joining us?&quot;">​</a></h2><p>If you care about technical community work and want to be part of this, the starting point is simple: <strong>subscribe to our mailing list at <a href="https://lists.neonephos.org/g/nnf-project-community-managers" target="_blank" rel="noreferrer">lists.neonephos.org/g/nnf-project-community-managers</a> and join the meetings.</strong> That&#39;s it — no formal application, no gatekeeping. Show up, share what you&#39;re working on, and help us build something useful together.</p><h2 id="practical-details" tabindex="-1">Practical details <a class="header-anchor" href="#practical-details" aria-label="Permalink to &quot;Practical details&quot;">​</a></h2><p><strong>Zoom Session Link</strong></p><p><a href="https://zoom-lfx.platform.linuxfoundation.org/meeting/96812983346?password=469046c8-1f65-4df8-8266-54a154ed0b47" target="_blank" rel="noreferrer">https://zoom-lfx.platform.linuxfoundation.org/meeting/96812983346?password=469046c8-1f65-4df8-8266-54a154ed0b47</a></p><p><strong>Shared notes</strong></p><p><a href="https://hackmd.io/@NNF/PCM/edit" target="_blank" rel="noreferrer">hackmd.io/@NNF/PCM/edit</a> — add topics before, during, and after each session.</p><p>Looking forward to building this with you.</p>',19)]))}const d=t(r,[["render",s]]);export{p as __pageData,d as default};
